import Logo from './Logo';

const Signup: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    orgName: '',
    gln: '',
    country: 'IN',
    sector: Sector.PHARMA, // Forced to Pharma
    role: UserRole.MANUFACTURER,
    positionLabel: '',
    password: '',
    erpType: ERPType.MANUAL,
    subCategories: [] as string[]
  });

  const [isCountryModalOpen, setIsCountryModalOpen] = useState(false);
  const [countrySearch, setCountrySearch] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);
  const navigate = useNavigate();
  const searchInputRef = useRef<HTMLInputElement>(null);

  const filteredCountries = useMemo(() => {
    return REGISTRY_CONFIG.filter(c => 
      c.name.toLowerCase().includes(countrySearch.toLowerCase()) || 
      c.code.toLowerCase().includes(countrySearch.toLowerCase())
    ).sort((a, b) => a.name.localeCompare(b.name));
  }, [countrySearch]);

  const selectedCountry = useMemo(() => 
    REGISTRY_CONFIG.find(c => c.code === formData.country), 
  [formData.country]);

  // Always use Pharma config
  const availablePositions = useMemo(() => {
    if (!selectedCountry) return [];
    const sectorConfig = selectedCountry.sectors[Sector.PHARMA];
    return sectorConfig ? sectorConfig.roles : [];
  }, [selectedCountry]);

  useEffect(() => {
    if (isCountryModalOpen) {
      setTimeout(() => searchInputRef.current?.focus(), 100);
    }
  }, [isCountryModalOpen]);

  useEffect(() => {
    if (availablePositions.length > 0) {
      setFormData(prev => ({
        ...prev,
        role: availablePositions[0].role,
        positionLabel: availablePositions[0].label
      }));
    }
  }, [availablePositions]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if (name === 'position') {
      const pos = availablePositions.find(p => p.label === value);
      if (pos) {
        setFormData(prev => ({ ...prev, role: pos.role, positionLabel: pos.label }));
      }
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const toggleSubCategory = (category: string) => {
    setFormData(prev => {
      const exists = prev.subCategories.includes(category);
      if (exists) {
        return { ...prev, subCategories: prev.subCategories.filter(c => c !== category) };
      } else {
        return { ...prev, subCategories: [...prev.subCategories, category] };
      }
    });
  };

  const handleCountrySelect = (code: string) => {
    setFormData(prev => ({ ...prev, country: code }));
    setIsCountryModalOpen(false);
    setCountrySearch('');
  };

  const handleGenerateGLN = (e: React.MouseEvent) => {
    e.preventDefault();
    const newGln = AuthService.generateGLN();
    setFormData(prev => ({ ...prev, gln: newGln }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (formData.gln.length !== 13) throw new Error('GLN must be exactly 13 digits.');

      await AuthService.signup(
        formData.name,
        formData.orgName,
        formData.gln,
        formData.role,
        formData.password,
        {
          country: formData.country,
          sector: Sector.PHARMA,
          positionLabel: formData.positionLabel,
          erpType: formData.erpType,
          erpStatus: formData.erpType === ERPType.MANUAL ? 'CONNECTED' : 'PENDING',
          subCategories: formData.subCategories
        }
      );
      navigate('/login');
    } catch (err: any) {
      setError(err.message || 'Failed to register.');
    } finally {
      setLoading(false);
    }
  };

  const getCountryFlag = (countryCode: string) => {
    if (!countryCode || countryCode.length !== 2) return '🌐';
    return countryCode
      .toUpperCase()
      .split('')
      .map(char => String.fromCodePoint(char.charCodeAt(0) + 127397))
      .join('');
  };

  return (
    <div className="min-h-screen bg-[#f8f9fa] flex items-center justify-center p-4">

      {isCountryModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/80 backdrop-blur-md p-4 animate-in fade-in duration-300">
           <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-xl overflow-hidden flex flex-col h-[80vh] max-h-[600px] animate-in zoom-in-95 duration-300">
              <div className="bg-slate-900 p-6 text-white shrink-0">
                 <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-black tracking-tight">Select Operational Market</h3>
                    <button onClick={() => setIsCountryModalOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                       <X size={20} />
                    </button>
                 </div>
                 <div className="relative group">
                    <Search className="absolute left-4 top-3 text-slate-500 group-focus-within:text-indigo-400 transition-colors" size={18} />
                    <input 
                      ref={searchInputRef}
                      type="text" 
                      placeholder="Search market..." 
                      value={countrySearch}
                      onChange={(e) => setCountrySearch(e.target.value)}
                      className="w-full pl-11 pr-4 py-2.5 bg-white/10 border border-white/20 rounded-2xl text-sm focus:ring-4 focus:ring-emerald-500/20 focus:border-emerald-500/50 outline-none transition-all placeholder:text-slate-500 font-medium"
                    />
                 </div>
              </div>

              <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                 <div className="grid grid-cols-1 gap-2">
                    {filteredCountries.map(c => (
                      <button 
                        key={c.code} 
                        type="button" 
                        onClick={() => handleCountrySelect(c.code)} 
                        className={`group flex items-center justify-between p-4 rounded-xl border-2 transition-all ${formData.country === c.code ? 'border-emerald-600 bg-emerald-50/20' : 'border-slate-50 hover:border-slate-200 bg-white'}`}
                      >
                        <div className="flex items-center gap-4">
                           <span className="text-2xl">{getCountryFlag(c.code)}</span>
                           <div className="text-left">
                              <p className={`font-black text-sm uppercase tracking-tight ${formData.country === c.code ? 'text-emerald-600' : 'text-slate-700'}`}>{c.name}</p>
                              <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">Node: {c.code}-PHARMA-NET</p>
                           </div>
                        </div>
                        {formData.country === c.code && <Check size={16} className="text-emerald-600" />}
                      </button>
                    ))}
                 </div>
              </div>
           </div>
        </div>
      )}

      <div className="max-w-4xl w-full bg-white rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.1)] overflow-hidden flex flex-col md:flex-row max-h-[90vh] min-h-[600px]">

        {/* Left Sidebar */}
        <div className="hidden md:flex w-[38%] bg-[#0f172a] p-8 text-white flex-col justify-between relative overflow-hidden">
          <div className="relative z-10">
            <div className="inline-block p-3 bg-white rounded-xl mb-6 shadow-xl">
              <Logo size="md" />
            </div>
            <h2 className="text-2xl font-black mb-2 tracking-tight">E-Ledger Pharma</h2>
            <p className="text-slate-400 text-xs leading-relaxed max-w-xs">
              Secure Pharmaceutical Supply Chain Network. DSCSA & GS1 Compliant.
            </p>
          </div>

          <div className="relative z-10 space-y-6">
             {[1, 2, 3, 4].map(s => (
                <div key={s} className="flex items-center gap-4">
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold transition-all ${step === s ? 'bg-emerald-600 shadow-[0_0_15px_rgba(16,185,129,0.4)]' : 'bg-slate-800 text-slate-500'}`}>{s}</div>
                  <p className={`font-bold text-xs tracking-wide ${step === s ? 'text-white' : 'text-slate-500'}`}>
                    {s === 1 ? 'Market Context' : s === 2 ? 'Identity & Role' : s === 3 ? 'ERP Protocol' : 'Finalize Keys'}
                  </p>
                </div>
             ))}
          </div>

          <div className="text-[10px] text-slate-600 font-bold uppercase tracking-[0.2em] relative z-10">
            Protocol: EPCIS 2.0 / 21 CFR Part 11
          </div>
        </div>

        {/* Right Form Area */}
        <div className="flex-1 flex flex-col bg-white overflow-hidden">
          <div className="p-8 pb-4 shrink-0 flex justify-between items-start">
             <div>
                <h2 className="text-2xl font-black text-slate-900 tracking-tight">Register Node</h2>
                <p className="text-slate-400 text-[11px] font-bold mt-0.5 uppercase tracking-widest">Stage {step} of 4</p>
             </div>
             <Link to="/login" className="px-4 py-1.5 bg-[#eff2f9] text-[#4d69ff] rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-[#e0e7ff] transition-all">Sign In</Link>
          </div>

          <div className="flex-1 overflow-y-auto px-8 pb-8 custom-scrollbar">
          <form onSubmit={handleSubmit} className="space-y-8">
            {step === 1 && (
              <div className="space-y-8 animate-in fade-in slide-in-from-right-4">
                {/* Active Market Card */}
                <div className="space-y-3">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Jurisdiction</label>
                  <div className="flex items-center justify-between p-5 bg-[#f0fdf4] border border-[#dcfce7] rounded-2xl">
                     <div className="flex items-center gap-4">
                        <div className="text-3xl font-bold text-emerald-200 font-mono tracking-tighter">
                          {formData.country}
                        </div>
                        <div className="text-left">
                           <p className="text-[9px] font-black text-emerald-700 uppercase tracking-widest leading-none mb-1">Active Market</p>
                           <p className="text-lg font-black text-slate-900 tracking-tight">{selectedCountry?.name}</p>
                        </div>
                     </div>
                     <button 
                        type="button" 
                        onClick={() => setIsCountryModalOpen(true)}
                        className="bg-white text-emerald-600 px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-emerald-50 transition-all border border-emerald-100"
                      >
                        Change <ChevronDown size={12} />
                     </button>
                  </div>
                  <p className="text-[10px] text-slate-400 italic font-medium px-1 leading-tight">Regulatory reporting and serialization rules adapt to {selectedCountry?.name} standards.</p>
                </div>

                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                   <div className="flex items-start gap-4">
                      <div className="p-3 bg-white border border-slate-100 rounded-xl shadow-sm text-emerald-600">
                         <Stethoscope size={24} />
                      </div>
                      <div>
                         <h4 className="font-bold text-slate-800 text-sm">Pharmaceutical Supply Chain</h4>
                         <p className="text-xs text-slate-500 mt-1 leading-relaxed">
                            This node will be initialized for drug tracking, cold-chain monitoring, and anti-counterfeit verification.
                         </p>
                      </div>
                   </div>
                </div>

                <button type="button" onClick={() => setStep(2)} className="w-full bg-[#0f172a] hover:bg-slate-800 text-white font-black py-4 rounded-2xl flex items-center justify-center gap-3 shadow-2xl transition-all active:scale-[0.98] uppercase text-xs tracking-[0.3em]">
                  Proceed to Identity <ArrowRight size={18} />
                </button>
              </div>
            )}

            {step === 2 && (
              <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
                <div className="space-y-3">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Organization Details</label>
                  <div className="grid grid-cols-1 gap-3">
                    <div className="relative">
                      <UserCircle className="absolute left-4 top-3 text-slate-400" size={18} />
                      <input name="name" required value={formData.name} onChange={handleChange} className="w-full pl-11 pr-4 py-3 bg-[#f8faff] border-transparent rounded-xl text-sm focus:bg-white focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-600 outline-none transition-all" placeholder="Authorized Signatory" />
                    </div>
                    <div className="relative">
                      <Building2 className="absolute left-4 top-3 text-slate-400" size={18} />
                      <input name="orgName" required value={formData.orgName} onChange={handleChange} className="w-full pl-11 pr-4 py-3 bg-[#f8faff] border-transparent rounded-xl text-sm focus:bg-white focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-600 outline-none transition-all" placeholder="Registered Entity Name" />
                    </div>
                  </div>
                </div>

                <div className="space-y-3">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Role & License</label>
                  <select name="position" value={formData.positionLabel} onChange={handleChange} className="w-full px-4 py-3 bg-[#f8faff] border-transparent rounded-xl outline-none text-sm font-bold text-slate-700 focus:bg-white">
                    {availablePositions.map(p => <option key={p.label} value={p.label}>{p.label}</option>)}
                  </select>

                  {/* Always Show Pharma Sub-Categories */}
                  <div className="space-y-2 pt-2">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1">
                      <Tags size={12} />
                      Operational Scope
                    </label>
                    <div className="flex flex-wrap gap-2">
                      {PHARMA_SUB_CATEGORIES.map(category => (
                        <button
                          key={category}
                          type="button"
                          onClick={() => toggleSubCategory(category)}
                          className={`px-3 py-1.5 rounded-lg text-[10px] font-bold border transition-all ${
                            formData.subCategories.includes(category)
                              ? 'bg-emerald-600 text-white border-emerald-600 shadow-md'
                              : 'bg-slate-50 text-slate-500 border-slate-200 hover:bg-slate-100'
                          }`}
                        >
                          {category}
                        </button>
                      ))}
                    </div>
                    <p className="text-[9px] text-slate-400 italic">Select all domains covered by your FDA/Drug Control license.</p>
                  </div>

                  <div className="flex gap-2">
                    <div className="relative flex-1">
                      <Globe className="absolute left-4 top-3 text-slate-400" size={18} />
                      <input name="gln" required maxLength={13} minLength={13} value={formData.gln} onChange={handleChange} className="w-full pl-11 pr-4 py-3 bg-[#f8faff] border-transparent rounded-xl text-sm font-mono focus:bg-white focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all" placeholder="GLN (Global Location Number)" />
                    </div>
                    <button type="button" onClick={handleGenerateGLN} className="px-4 bg-slate-100 rounded-xl hover:bg-slate-200 transition-colors" title="Generate Demo GLN">
                      <RefreshCw size={18} className="text-slate-600" />
                    </button>
                  </div>
                </div>

                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setStep(1)} className="flex-1 py-4 border-2 border-[#eff2f9] rounded-xl text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 hover:bg-slate-50 transition-colors">Back</button>
                  <button type="button" onClick={() => setStep(3)} className="flex-[2] bg-[#0f172a] text-white font-black py-4 rounded-xl uppercase text-[10px] tracking-[0.2em] shadow-xl">Integrate ERP</button>
                </div>
              </div>
            )}

            {step === 3 && (
              <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
                <div className="bg-[#f0f4ff] p-5 rounded-2xl flex gap-4 border border-[#e0e7ff]">
                  <div className="p-3 bg-[#4d69ff] rounded-xl text-white shadow-lg shrink-0 h-fit">
                    <Cpu size={22} />
                  </div>
                  <div>
                    <h4 className="font-black text-[#0f172a] text-[13px] uppercase tracking-tight">Middleware Integration</h4>
                    <p className="text-[11px] text-[#5c6b8c] leading-relaxed font-medium mt-1">Connect your internal system to the blockchain gateway.</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 gap-2">
                   {Object.values(ERPType).map(type => (
                     <button key={type} type="button" onClick={() => setFormData({...formData, erpType: type})} className={`p-4 rounded-xl flex justify-between items-center transition-all ${formData.erpType === type ? 'bg-white border-2 border-[#4d69ff] shadow-lg' : 'bg-[#f8faff] border-2 border-transparent hover:bg-[#f1f5ff]'}`}>
                        <div className="flex flex-col text-left">
                          <span className={`font-black text-[11px] uppercase tracking-widest ${formData.erpType === type ? 'text-[#4d69ff]' : 'text-slate-400'}`}>{type}</span>
                          <span className="text-[9px] text-slate-500 font-bold mt-0.5 uppercase tracking-tighter">{type === ERPType.MANUAL ? 'Standard Web Terminal' : 'API Connection Hook'}</span>
                        </div>
                        {formData.erpType === type && <div className="w-5 h-5 bg-[#4d69ff] rounded-full flex items-center justify-center text-white"><Check size={12} strokeWidth={4} /></div>}
                     </button>
                   ))}
                </div>

                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setStep(2)} className="flex-1 py-4 border-2 border-[#eff2f9] rounded-xl text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Back</button>
                  <button type="button" onClick={() => setStep(4)} className="flex-[2] bg-[#0f172a] text-white font-black py-4 rounded-xl uppercase text-[10px] tracking-[0.2em] shadow-xl">Final Security</button>
                </div>
              </div>
            )}

            {step === 4 && (
              <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
                <div className="space-y-3">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Master Node Secret</label>
                  <div className="relative">
                    <Lock className="absolute left-4 top-3 text-slate-400" size={18} />
                    <input name="password" type="password" required value={formData.password} onChange={handleChange} className="w-full pl-11 pr-4 py-3 bg-[#f8faff] border-transparent rounded-xl text-sm focus:bg-white focus:ring-4 focus:ring-[#4d69ff]/10 outline-none" placeholder="••••••••••••" />
                  </div>
                </div>

                <div className="bg-[#f8faff] p-6 rounded-2xl border border-[#e8effd] space-y-4">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                    <CheckCircle2 size={14} className="text-emerald-500" />
                    Terminal Summary
                  </h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <span className="block text-[9px] font-bold text-slate-400 uppercase tracking-tighter mb-1">Region Node</span>
                      <span className="text-xs font-black text-slate-900 truncate block">{selectedCountry?.name}</span>
                    </div>
                    <div>
                      <span className="block text-[9px] font-bold text-slate-400 uppercase tracking-tighter mb-1">Sector Protocol</span>
                      <span className="text-xs font-black text-slate-900 truncate block">PHARMA (DSCSA)</span>
                    </div>
                  </div>
                  {formData.subCategories.length > 0 && (
                    <div>
                      <span className="block text-[9px] font-bold text-slate-400 uppercase tracking-tighter mb-1">Operations</span>
                      <div className="flex flex-wrap gap-1">
                        {formData.subCategories.map(sub => (
                          <span key={sub} className="text-[9px] bg-emerald-100 text-emerald-800 px-1.5 py-0.5 rounded-md font-bold uppercase">{sub}</span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex gap-3 pt-2">
                  <button type="button" onClick={() => setStep(3)} className="flex-1 py-4 border-2 border-[#eff2f9] rounded-xl text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Back</button>
                  <button type="submit" disabled={loading} className="flex-[2] bg-[#4d69ff] text-white font-black py-4 rounded-xl shadow-xl shadow-[#4d69ff]/30 flex items-center justify-center gap-3 transition-all hover:scale-[1.02] active:scale-[0.98] uppercase text-[10px] tracking-[0.2em]">
                    {loading ? <Loader2 size={18} className="animate-spin" /> : <span>Initialize Terminal</span>}
                  </button>
                </div>
              </div>
            )}
          </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Signup;

import React, { useState } from 'react';
// Added Link to imports from react-router-dom
import { useNavigate, Link } from 'react-router-dom';
import { AuthService } from '../services/authService';
import { User } from '../types';
import { ShieldCheck, ArrowRight, Loader2, KeyRound, Pill, Globe, Box, Database, Lock, Activity, Truck } from 'lucide-react';
import Logo from './Logo';

const LandingPage: React.FC<{ onLogin: (user: User) => void }> = ({ onLogin }) => {
  const navigate = useNavigate();
  const [gln, setGln] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const user = await AuthService.login(gln, password);
      if (user) {
        onLogin(user);
        navigate('/dashboard');
      } else {
        setError('Authorization failed. Invalid credentials.');
      }
    } catch (err) {
      setError('Network synchronization error.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white font-sans">
      <nav className="fixed top-0 w-full z-50 bg-white/80 backdrop-blur-md border-b border-slate-100">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Logo size="md" />
            <div>
                <span className="text-2xl font-black text-slate-900 tracking-tighter uppercase block leading-none">E-Ledger</span>
                <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest block leading-none">Pharma Chain</span>
            </div>
          </div>
        </div>
      </nav>

      <section className="relative pt-48 pb-32 overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full opacity-5 pointer-events-none">
          <div className="absolute top-20 left-10 w-96 h-96 bg-emerald-600 rounded-full blur-[120px]"></div>
          <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
        </div>

        <div className="max-w-7xl mx-auto px-6 relative z-10">
          <div className="flex flex-col lg:flex-row items-center gap-24">

            <div className="flex-1 text-center lg:text-left">
              <div className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-50 border border-emerald-100 rounded-full text-emerald-700 text-[10px] font-black uppercase tracking-widest mb-8">
                <Globe size={14} />
                Global Pharmaceutical Protocol
              </div>
              <h1 className="text-6xl md:text-8xl font-black text-slate-900 leading-[1.1] mb-8 tracking-tighter">
                Patient <br/>
                <span className="text-emerald-600">Safety First.</span>
              </h1>
              <p className="text-xl text-slate-500 max-w-xl leading-relaxed mb-12">
                A blockchain backbone for the life sciences industry. Ensure DSCSA compliance, track cold-chain integrity, and verify authenticity from factory to pharmacy.
              </p>

              <div className="flex flex-wrap justify-center lg:justify-start gap-12 text-slate-400">
                <div className="flex items-center gap-2 font-bold uppercase tracking-widest text-[10px]">
                   <Box size={24} className="text-emerald-500" />
                   Serialization
                </div>
                <div className="flex items-center gap-2 font-bold uppercase tracking-widest text-[10px]">
                   <Activity size={24} className="text-emerald-500" />
                   Safety Monitoring
                </div>
                <div className="flex items-center gap-2 font-bold uppercase tracking-widest text-[10px]">
                   <Truck size={24} className="text-emerald-500" />
                   Cold Chain
                </div>
              </div>
            </div>

            <div className="w-full max-w-md">
              <div className="bg-slate-900 rounded-[3rem] p-10 md:p-14 shadow-2xl relative">
                <div className="absolute -top-6 -right-6 w-16 h-16 bg-emerald-600 rounded-2xl flex items-center justify-center shadow-xl text-white">
                  <Lock size={32} />
                </div>

                <h2 className="text-2xl font-black text-white mb-2 tracking-tight">Partner Login</h2>
                <p className="text-slate-500 text-sm mb-10">Establish secure node connection</p>

                {error && <div className="mb-6 p-4 bg-red-900/20 border border-red-900/40 text-red-400 text-xs font-bold rounded-2xl text-center">{error}</div>}

                <form onSubmit={handleLogin} className="space-y-6">
                  <div>
                    <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">License No / GLN</label>
                    <div className="relative">
                      <KeyRound className="absolute left-4 top-4 text-slate-600" size={18} />
                      <input
                        type="text"
                        required
                        value={gln}
                        onChange={(e) => setGln(e.target.value)}
                        className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-12 py-4 text-white text-sm font-mono focus:ring-2 focus:ring-emerald-600 outline-none transition-all"
                        placeholder="0000000000000"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Private Key</label>
                    <div className="relative">
                      <Database className="absolute left-4 top-4 text-slate-600" size={18} />
                      <input
                        type="password"
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-12 py-4 text-white text-sm focus:ring-2 focus:ring-emerald-600 outline-none transition-all"
                        placeholder="••••••••"
                      />
                    </div>
                  </div>

                  <button
                    type="submit"
                    disabled={loading}
                    className="w-full bg-white hover:bg-slate-100 text-slate-900 font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-70"
                  >
                    {loading ? <Loader2 className="animate-spin" size={24} /> : (
                      <>
                        <span>Initialize Terminal</span>
                        <ArrowRight size={20} />
                      </>
                    )}
                  </button>

                  <div className="pt-6 text-center">
                    <Link to="/signup" className="text-emerald-400 font-bold text-xs uppercase tracking-widest hover:text-emerald-300 transition-colors">Request ATP Credentials</Link>
                  </div>
                </form>
              </div>
            </div>

          </div>
        </div>
      </section>
    </div>
  );
};

export default LandingPage;

import React, { useState, useEffect } from 'react';
import { User, Batch, UserRole, BatchStatus, GSTDetails, EWayBill, ReturnReason, Sector } from '../types';
import { LedgerService } from '../services/ledgerService';
import { AuthService } from '../services/authService';
import { Plus, Search, ArrowRight, Package, Zap, Truck, ArrowUpRight, ArrowDownLeft, Send, CheckSquare, Square, Layers, RotateCcw, AlertTriangle, MapPin, IndianRupee, Printer, Filter, Percent, Landmark, Pill } from 'lucide-react';
import { Link } from 'react-router-dom';
import BatchLabel from './BatchLabel';
import TransferModal from './TransferModal'; 
import { toast } from 'react-toastify';

interface BatchManagerProps {
  user: User;
}

const BatchManager: React.FC<BatchManagerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'shipments'>('inventory');
  const [batches, setBatches] = useState<Batch[]>([]);
  const [showCreateModal, setShowCreateModal] = useState(false);

  const [selectedBatchIds, setSelectedBatchIds] = useState<string[]>([]);
  const [showTransferModal, setShowTransferModal] = useState(false);

  // Return States
  const [showReturnModal, setShowReturnModal] = useState(false);
  const [selectedBatchForReturn, setSelectedBatchForReturn] = useState<Batch | null>(null);

  // Recall States
  const [showRecallModal, setShowRecallModal] = useState(false);
  const [selectedBatchForRecall, setSelectedBatchForRecall] = useState<Batch | null>(null);
  const [recallReason, setRecallReason] = useState('');

  // Print States
  const [showPrintModal, setShowPrintModal] = useState(false);

  // Filter State
  const [statusFilter, setStatusFilter] = useState<string>('ALL');

  const [loading, setLoading] = useState(true);

  // Pharma-Specific Initial Form State
  const getInitialFormData = () => ({
    gtin: '',
    productName: '',
    lotNumber: '',
    expiryDate: '',
    quantity: 0,
    unit: 'Packs',
    alcoholContent: 0, // Not used in Pharma UI but kept for type compatibility
    dosageForm: '',
    category: 'Prescription (Rx)',
    isDutyPaid: true, // Pharma usually tax paid at source or irrelevant for "duty" status (unlike Excise)
    hsnCode: '3004',
    taxableValue: 0,
    taxRate: 12 // Standard GST for medicines often 12% or 18%
  });

  const [formData, setFormData] = useState(getInitialFormData());

  // Return Form State
  const [returnData, setReturnData] = useState({
    toGLN: '',
    reason: ReturnReason.DAMAGED,
    refundAmount: 0,
    quantityToReturn: 1
  });

  const fetchData = async () => {
    setLoading(true);
    const data = await LedgerService.getBatches(user);
    setBatches(data);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, [user]);

  const toggleSelection = (id: string) => {
    if (selectedBatchIds.includes(id)) {
      setSelectedBatchIds(prev => prev.filter(bid => bid !== id));
    } else {
      setSelectedBatchIds(prev => [...prev, id]);
    }
  };

  const getSelectedBatches = () => {
    return batches.filter(b => selectedBatchIds.includes(b.batchID));
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const taxAmount = (formData.taxableValue * formData.taxRate) / 100;
      const batchPayload: Partial<Batch> = {
        ...formData,
        sector: Sector.PHARMA,
        country: user.country,
        dutyPaid: formData.isDutyPaid,
        status: BatchStatus.CREATED, // Pharma starts as CREATED usually
        taxAmount: taxAmount
      };

      const batchID = await LedgerService.createBatch(batchPayload, user);
      toast.success(`Batch ${batchID} Registered!`);
      setShowCreateModal(false);
      fetchData(); 
      setFormData(getInitialFormData());
    } catch (err: any) {
      toast.error(err.message || 'Failed to create batch');
    }
  };

  const handleTransferSubmit = async (toGLN: string, toName: string, gst?: GSTDetails, ewbPartial?: Partial<EWayBill>, payment?: any) => {
    const batchesToTransfer = getSelectedBatches();
    if (batchesToTransfer.length === 0) return;

    try {
        await LedgerService.transferBatches(
            batchesToTransfer.map(b => b.batchID),
            toGLN,
            toName,
            user,
            gst,
            ewbPartial,
            payment
        );
        toast.success(`Dispatched ${batchesToTransfer.length} items to ${toName}`);
        fetchData();
        setSelectedBatchIds([]);
        setShowTransferModal(false);
    } catch (err: any) {
        toast.error(`Transfer failed: ${err.message || err}`);
    }
  };

  const handleReturnSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBatchForReturn) return;

    try {
      await LedgerService.returnBatch(
        selectedBatchForReturn.batchID,
        returnData.toGLN,
        returnData.reason,
        returnData.quantityToReturn,
        user,
        returnData.refundAmount
      );
      toast.success(`Batch marked as RETURNED.`);
      setShowReturnModal(false);
      setSelectedBatchForReturn(null);
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Return failed');
    }
  };

  const handleRecallSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBatchForRecall || !recallReason) return;

    try {
      await LedgerService.recallBatch(
        selectedBatchForRecall.batchID,
        recallReason,
        user
      );
      toast.error(`BATCH RECALLED: ${selectedBatchForRecall.batchID}`);
      setShowRecallModal(false);
      setSelectedBatchForRecall(null);
      setRecallReason('');
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Recall failed');
    }
  };

  const handleAutoFill = () => {
    const pharmaProducts = ['Amoxicillin 500mg', 'Paracetamol IP', 'Insulin Glargine', 'Azithromycin Tabs', 'Vitamix-D3'];
    const dosageForms = ['Tablet', 'Capsule', 'Injectable', 'Syrup', 'Tablet'];
    const categories = ['Prescription (Rx)', 'OTC', 'Biologic', 'Prescription (Rx)', 'Supplement'];

    const idx = Math.floor(Math.random() * pharmaProducts.length);
    const mockProduct = pharmaProducts[idx];
    const mockDosage = dosageForms[idx];
    const mockCategory = categories[idx];

    const randomLot = `LOT-${new Date().getFullYear()}-${Math.floor(Math.random() * 10000)}`;
    const futureDate = new Date();
    futureDate.setFullYear(futureDate.getFullYear() + 2);

    setFormData({
      gtin: AuthService.generateGTIN(),
      productName: mockProduct,
      lotNumber: randomLot,
      expiryDate: futureDate.toISOString().split('T')[0],
      quantity: Math.floor(Math.random() * 500) + 50,
      unit: 'Packs',
      alcoholContent: 0,
      dosageForm: mockDosage,
      category: mockCategory,
      isDutyPaid: true,
      hsnCode: '3004',
      taxableValue: (Math.floor(Math.random() * 500) + 50) * 450,
      taxRate: 12
    });
    toast.info(`Pharma data auto-filled`);
  };

  const getStatusColor = (status: BatchStatus) => {
    switch (status) {
      case BatchStatus.CREATED: return 'bg-slate-100 text-slate-600 border-slate-200';
      case BatchStatus.BONDED: return 'bg-amber-100 text-amber-800 border-amber-200';
      case BatchStatus.DUTY_PAID: return 'bg-green-100 text-green-800 border-green-200';
      case BatchStatus.IN_TRANSIT: return 'bg-blue-100 text-blue-800 border-blue-200';
      case BatchStatus.RECEIVED: return 'bg-indigo-100 text-indigo-800 border-indigo-200';
      case BatchStatus.SOLD: return 'bg-slate-200 text-slate-500 border-slate-200';
      case BatchStatus.QUARANTINED: return 'bg-red-100 text-red-800 border-red-200';
      case BatchStatus.RECALLED: return 'bg-red-600 text-white border-red-700 shadow-sm';
      case BatchStatus.RETURNED: return 'bg-orange-100 text-orange-800 border-orange-200';
      case BatchStatus.DESTROYED: return 'bg-gray-800 text-gray-100 border-gray-900';
      default: return 'bg-gray-100 text-gray-600 border-gray-200';
    }
  };

  return (
    <div className="w-full">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
        <div>
            <h2 className="text-2xl font-bold text-slate-800">Pharmaceutical Inventory</h2>
            <p className="text-sm text-slate-500">Track drug batches, expiry, and compliance status.</p>
        </div>

        <div className="flex gap-2 w-full sm:w-auto">
             <div className="flex bg-slate-100 p-1 rounded-lg">
                <button
                   onClick={() => setActiveTab('inventory')}
                   className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${activeTab === 'inventory' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-900'}`}
                >
                    Current Stock
                </button>
                <button
                   onClick={() => setActiveTab('shipments')}
                   className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${activeTab === 'shipments' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-900'}`}
                >
                    Logistics Logs
                </button>
             </div>

            {user.role === UserRole.MANUFACTURER && (
            <button 
                onClick={() => setShowCreateModal(true)}
                className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center justify-center space-x-2 transition-colors shadow-sm ml-auto"
            >
                <Plus size={18} />
                <span className="hidden sm:inline">Register Batch</span>
            </button>
            )}
        </div>
      </div>

      {activeTab === 'inventory' && (
      <>
        <div className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row items-center gap-4 justify-between">
            <div className="flex items-center gap-4 w-full md:w-auto flex-1">
                <div className="flex items-center space-x-3 w-full md:w-auto flex-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2">
                    <Search className="text-slate-400 shrink-0" size={18} />
                    <input 
                        type="text" 
                        placeholder="Search medicines..." 
                        className="flex-1 outline-none text-slate-700 bg-transparent placeholder-slate-400 min-w-0 text-sm"
                    />
                </div>

                <div className="relative shrink-0">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Filter size={16} className="text-slate-400" />
                    </div>
                    <select
                        value={statusFilter}
                        onChange={(e) => setStatusFilter(e.target.value)}
                        className="pl-10 pr-8 py-2 border border-slate-200 rounded-lg text-sm text-slate-600 bg-white focus:ring-2 focus:ring-emerald-500 outline-none appearance-none cursor-pointer hover:border-slate-300 transition-colors shadow-sm"
                    >
                        <option value="ALL">All Status</option>
                        {Object.values(BatchStatus).map((status) => (
                           <option key={status} value={status}>{status.replace('_', ' ')}</option>
                        ))}
                    </select>
                </div>
            </div>

            {selectedBatchIds.length > 0 && (
                <div className="flex flex-wrap items-center gap-2 w-full md:w-auto justify-between md:justify-end animate-in fade-in slide-in-from-right-2">
                    <span className="text-sm font-semibold text-slate-600 mr-2">{selectedBatchIds.length} Selected</span>

                    <button 
                        onClick={() => setShowPrintModal(true)}
                        className="bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 shadow-md hover:bg-slate-700 transition-colors"
                    >
                        <Printer size={16} />
                        <span>Print GS1 Labels</span>
                    </button>

                    <button 
                        onClick={() => setShowTransferModal(true)}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 shadow-md transition-colors"
                    >
                        <Layers size={16} />
                        <span>Dispatch / Transfer</span>
                    </button>
                </div>
            )}
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            {loading ? (
            <div className="p-8 text-center text-slate-500">Syncing with Distributed Chain...</div>
            ) : (
            <div className="overflow-x-auto">
                <table className="w-full text-left min-w-[800px]">
                <thead className="bg-slate-50 border-b border-slate-200">
                    <tr>
                    <th className="px-4 py-4 w-10"></th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Product / Dosage</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">GTIN</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Category</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Status</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Action</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {batches
                      .filter(b => statusFilter === 'ALL' || b.status === statusFilter)
                      .map((batch) => {
                        const canTransfer = batch.currentOwnerGLN === user.gln && batch.status !== 'SOLD' && batch.status !== 'IN_TRANSIT' && batch.status !== 'RETURNED' && batch.status !== 'RECALLED';
                        const isSelected = selectedBatchIds.includes(batch.batchID);
                        const canRecall = batch.status !== 'RECALLED' && (
                           (user.role === UserRole.MANUFACTURER && batch.manufacturerGLN === user.gln) ||
                           user.role === UserRole.REGULATOR
                        );

                        return (
                        <tr key={batch.batchID} className={`hover:bg-slate-50 transition-colors ${isSelected ? 'bg-indigo-50/50' : ''}`}>
                            <td className="px-4 py-4 text-center">
                                {canTransfer ? (
                                    <button 
                                        onClick={() => toggleSelection(batch.batchID)}
                                        className="text-slate-400 hover:text-indigo-600"
                                    >
                                        {isSelected ? <CheckSquare className="text-indigo-600" /> : <Square />}
                                    </button>
                                ) : (
                                    <Square className="text-slate-200 cursor-not-allowed" />
                                )}
                            </td>
                            <td className="px-6 py-4">
                            <div className="flex items-center space-x-3">
                                <div className="p-2 bg-emerald-50 rounded-lg text-emerald-600">
                                    <Pill size={20} />
                                </div>
                                <div>
                                <p className="font-medium text-slate-800">{batch.productName}</p>
                                <p className="text-xs text-slate-500 font-mono">
                                    {batch.batchID} 
                                    {batch.dosageForm ? ` • ${batch.dosageForm}` : ''}
                                </p>
                                </div>
                            </div>
                            </td>
                            <td className="px-6 py-4 font-mono text-sm text-slate-600">{batch.gtin}</td>
                            <td className="px-6 py-4 text-sm text-slate-600">{batch.category || 'N/A'}</td>
                            <td className="px-6 py-4">
                            <span className={`px-3 py-1 rounded-full text-xs font-bold border ${getStatusColor(batch.status)} whitespace-nowrap`}>
                                {batch.status.replace('_', ' ')}
                            </span>
                            </td>
                            <td className="px-6 py-4 text-right flex items-center justify-end space-x-4">
                                {canTransfer && (
                                    <>
                                        <button 
                                            onClick={() => { setSelectedBatchIds([batch.batchID]); setShowTransferModal(true); }}
                                            className="text-indigo-600 hover:text-indigo-800 text-xs font-bold uppercase tracking-wider flex items-center gap-1"
                                        >
                                            <Send size={14} />
                                            <span>Move</span>
                                        </button>
                                        <button 
                                            onClick={() => { 
                                                setSelectedBatchForReturn(batch); 
                                                const available = batch.quantity - (batch.totalReturnedQuantity || 0);
                                                setReturnData({ ...returnData, toGLN: batch.manufacturerGLN, quantityToReturn: available }); 
                                                setShowReturnModal(true); 
                                            }}
                                            className="text-orange-600 hover:text-orange-800 text-xs font-bold uppercase tracking-wider flex items-center gap-1"
                                        >
                                            <RotateCcw size={14} />
                                            <span>Return</span>
                                        </button>
                                    </>
                                )}

                                {canRecall && (
                                    <button 
                                        onClick={() => {
                                            setSelectedBatchForRecall(batch);
                                            setShowRecallModal(true);
                                        }}
                                        className="text-red-600 hover:text-red-800 text-xs font-bold uppercase tracking-wider flex items-center gap-1"
                                        title="Initiate Product Recall"
                                    >
                                        <AlertTriangle size={14} />
                                        <span>Recall</span>
                                    </button>
                                )}

                                <Link 
                                    to={`/trace/${batch.batchID}`}
                                    className="inline-flex items-center space-x-1 text-blue-600 hover:text-blue-800 text-sm font-medium"
                                >
                                    <span>Trace</span>
                                    <ArrowRight size={16} />
                                </Link>
                            </td>
                        </tr>
                    )})}
                    {batches.filter(b => statusFilter === 'ALL' || b.status === statusFilter).length === 0 && (
                        <tr>
                            <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                                <div className="flex flex-col items-center gap-2">
                                    <Package size={32} className="opacity-20" />
                                    <p>No batches found with the selected filter.</p>
                                </div>
                            </td>
                        </tr>
                    )}
                </tbody>
                </table>
            </div>
            )}
        </div>
      </>
      )}

      {activeTab === 'shipments' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-6 border-b border-slate-100 flex items-center gap-3">
                <Truck className="text-blue-600" />
                <h3 className="font-bold text-slate-800">Transport & Permits</h3>
            </div>
            <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase">
                        <tr>
                            <th className="px-6 py-4">Direction</th>
                            <th className="px-6 py-4">Partner (GLN)</th>
                            <th className="px-6 py-4">Product / Batch</th>
                            <th className="px-6 py-4">E-Way Bill Details</th>
                            <th className="px-6 py-4 text-right">Status</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {batches.flatMap(b => {
                            const events = [];
                            const dispatch = b.trace.find(t => t.type === 'DISPATCH' && t.actorGLN === user.gln);
                            if (dispatch) events.push({
                                type: 'OUTBOUND',
                                partner: dispatch.metadata?.recipientGLN || 'Unknown',
                                partnerName: dispatch.metadata?.recipient || 'Unknown',
                                date: dispatch.timestamp,
                                batch: b,
                                ewb: dispatch.metadata?.ewayBill
                            });
                            const receive = b.trace.find(t => t.type === 'RECEIVE' && t.actorGLN === user.gln);
                            if (receive) events.push({
                                type: 'INBOUND',
                                partner: b.trace.find(t => t.type === 'DISPATCH' && new Date(t.timestamp) < new Date(receive.timestamp))?.actorGLN || b.manufacturerGLN,
                                partnerName: 'Supplier',
                                date: receive.timestamp,
                                batch: b,
                                ewb: null
                            });
                            return events;
                        }).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map((log, idx) => (
                            <tr key={idx} className="hover:bg-slate-50">
                                <td className="px-6 py-4">
                                    {log.type === 'OUTBOUND' ? (
                                        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold bg-indigo-50 text-indigo-700">
                                            <ArrowUpRight size={14} /> Sent
                                        </span>
                                    ) : (
                                        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-50 text-emerald-700">
                                            <ArrowDownLeft size={14} /> Received
                                        </span>
                                    )}
                                </td>
                                <td className="px-6 py-4">
                                    <p className="font-medium text-slate-800">{log.partnerName}</p>
                                    <p className="font-mono text-xs text-slate-400">{log.partner}</p>
                                </td>
                                <td className="px-6 py-4">
                                    <p className="text-sm font-medium text-slate-800">{log.batch.productName}</p>
                                    <p className="font-mono text-xs text-slate-500">{log.batch.batchID}</p>
                                </td>
                                <td className="px-6 py-4 text-sm text-slate-500">
                                    {log.ewb ? (
                                        <div className="flex flex-col text-xs space-y-1">
                                          <div className="flex items-center gap-1 text-slate-700 font-bold">
                                            <Truck size={12} />
                                            <span>{log.ewb.vehicleNo}</span>
                                          </div>
                                          <div className="flex items-center gap-1">
                                            <MapPin size={12} />
                                            <span>{log.ewb.fromPlace} ➝ {log.ewb.toPlace}</span>
                                          </div>
                                          <span className="text-slate-400">Dist: {log.ewb.distanceKm} km</span>
                                        </div>
                                    ) : (
                                        <span className="text-slate-300 italic">--</span>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <Link to={`/trace/${log.batch.batchID}`} className="text-blue-600 hover:underline text-xs font-bold">
                                        View
                                    </Link>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
      )}

      {showPrintModal && (
        <div className="fixed inset-0 z-[100] bg-white overflow-y-auto">
            <div className="p-4 bg-slate-900 text-white flex justify-between items-center print:hidden sticky top-0 z-50 shadow-md">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-indigo-600 rounded-lg">
                        <Printer size={20} className="text-white" />
                    </div>
                    <div>
                        <h3 className="font-bold">Label Printing Queue</h3>
                        <p className="text-xs text-slate-400">{selectedBatchIds.length} stickers ready for thermal printer</p>
                    </div>
                </div>
                <div className="flex gap-3">
                    <button 
                        onClick={() => setShowPrintModal(false)} 
                        className="px-4 py-2 text-slate-300 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
                    >
                        Close
                    </button>
                    <button 
                        onClick={() => window.print()} 
                        className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-lg font-bold shadow-lg flex items-center gap-2"
                    >
                        <Printer size={18} />
                        <span>Print All</span>
                    </button>
                </div>
            </div>

            <div className="p-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8 print:block print:p-0 print:gap-0">
               {getSelectedBatches().map((batch, idx) => (
                   <div key={batch.batchID} className="flex justify-center print:break-inside-avoid print:mb-4 print:page-break-after-auto print:flex print:justify-start">
                      <BatchLabel 
                          gtin={batch.gtin} 
                          lot={batch.lotNumber} 
                          expiry={batch.expiryDate} 
                          productName={batch.productName} 
                          status={batch.status}
                          hidePrintButton={true}
                      />
                   </div>
               ))}
            </div>

            <div className="print:hidden p-8 text-center text-slate-400 text-sm">
                <p>Preview Mode. Use Ctrl+P or the Print button to send to printer.</p>
            </div>
        </div>
      )}

      {showCreateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 overflow-y-auto">
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-5xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]">
            <div className="flex-1 p-4 md:p-8 flex flex-col overflow-y-auto">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-bold text-xl text-slate-800">Register New Batch</h3>
                <button onClick={() => setShowCreateModal(false)} className="md:hidden text-slate-400 hover:text-slate-600">✕</button>
              </div>
              <div className="mb-4">
                <button onClick={handleAutoFill} className="w-full bg-emerald-50 hover:bg-emerald-100 text-emerald-700 font-semibold py-2 rounded-lg flex items-center justify-center space-x-2 transition-colors border border-emerald-200">
                  <Zap size={16} className="text-emerald-600 fill-current" />
                  <span>Auto-Fill (Simulate Pharma Data)</span>
                </button>
              </div>
              <form onSubmit={handleCreate} className="space-y-5 flex-1">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {/* Left Column: Product Info */}
                  <div className="space-y-4">
                    <h4 className="text-sm font-bold text-slate-700 flex items-center gap-2 border-b pb-1">
                      <Package size={16} className="text-emerald-600" />
                      Drug Specifics
                    </h4>
                    <div><label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">Product Name</label><input required type="text" className="w-full border border-slate-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition text-sm" value={formData.productName} onChange={e => setFormData({...formData, productName: e.target.value})} placeholder="e.g. Amoxicillin 500mg" /></div>

                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">Category</label>
                        <select className="w-full border border-slate-300 rounded-lg px-4 py-2 text-sm bg-white" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                            <option value="Prescription (Rx)">Prescription (Rx)</option>
                            <option value="OTC">Over-the-Counter (OTC)</option>
                            <option value="Controlled">Controlled Substance</option>
                            <option value="Biologic">Biologic / Vaccine</option>
                            <option value="Medical Device">Medical Device</option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">Form / Strength</label>
                        <input required type="text" className="w-full border border-slate-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition text-sm" value={formData.dosageForm} onChange={e => setFormData({...formData, dosageForm: e.target.value})} placeholder="e.g. 500mg Tablet" />
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div><label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">GTIN</label><input required maxLength={14} minLength={14} type="text" className="w-full border border-slate-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition font-mono text-sm" value={formData.gtin} onChange={e => setFormData({...formData, gtin: e.target.value})} placeholder="00089012345678" /></div>
                      <div><label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">Lot / Batch No</label><input required type="text" className="w-full border border-slate-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition text-sm" value={formData.lotNumber} onChange={e => setFormData({...formData, lotNumber: e.target.value})} placeholder="LOT-2024-X" /></div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div><label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">Expiry Date</label><input required type="date" className="w-full border border-slate-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition text-sm" value={formData.expiryDate} onChange={e => setFormData({...formData, expiryDate: e.target.value})} /></div>
                      <div><label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">Quantity ({formData.unit})</label><input required type="number" className="w-full border border-slate-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition text-sm" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value)})} /></div>
                    </div>
                  </div>

                  {/* Right Column: Financial Compliance */}
                  <div className="space-y-4">
                    <h4 className="text-sm font-bold text-slate-700 flex items-center gap-2 border-b pb-1">
                      <Landmark size={16} className="text-emerald-600" />
                      Tax & GST Compliance
                    </h4>

                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">HSN Code</label>
                        <input required type="text" className="w-full border border-slate-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition text-sm font-mono" value={formData.hsnCode} onChange={e => setFormData({...formData, hsnCode: e.target.value})} />
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">Tax Rate (%)</label>
                        <div className="relative">
                          <Percent size={14} className="absolute right-3 top-2.5 text-slate-400" />
                          <input required type="number" className="w-full border border-slate-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition text-sm" value={formData.taxRate} onChange={e => setFormData({...formData, taxRate: parseInt(e.target.value)})} />
                        </div>
                      </div>
                    </div>

                    <div>
                      <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1.5">Taxable Value (Local Currency)</label>
                      <div className="relative">
                        <IndianRupee size={14} className="absolute left-3 top-2.5 text-slate-400" />
                        <input required type="number" className="w-full border border-slate-300 rounded-lg pl-8 pr-4 py-2 focus:ring-2 focus:ring-blue-500 outline-none transition text-sm font-bold" value={formData.taxableValue} onChange={e => setFormData({...formData, taxableValue: parseInt(e.target.value)})} />
                      </div>
                    </div>

                    <div className="bg-emerald-50 p-3 rounded-lg border border-emerald-100">
                      <div className="flex justify-between text-[10px] font-bold text-emerald-700 uppercase mb-1">
                        <span>GST Projection</span>
                        <span>{((formData.taxableValue * formData.taxRate) / 100).toLocaleString()}</span>
                      </div>
                      <div className="w-full bg-emerald-200 h-1 rounded-full overflow-hidden">
                        <div className="bg-emerald-600 h-full w-[100%]"></div>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="pt-6 flex justify-end space-x-3 mt-auto">
                    <button type="button" onClick={() => setShowCreateModal(false)} className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-lg font-medium transition-colors">Cancel</button>
                    <button type="submit" className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg font-bold shadow-md transition-all transform hover:scale-[1.02]">Register Batch & Generate ID</button>
                </div>
              </form>
            </div>
            <div className="w-full md:w-80 bg-slate-50 border-t md:border-t-0 md:border-l border-slate-200 p-6 md:p-8 flex flex-col items-center justify-center">
                <div className="mb-6 text-center">
                    <h4 className="text-sm font-bold text-slate-600 uppercase tracking-wide">Security Feature</h4>
                    <p className="text-xs text-slate-400 mt-1">Serialized 2D DataMatrix</p>
                </div>
                <BatchLabel 
                    gtin={formData.gtin} 
                    lot={formData.lotNumber} 
                    expiry={formData.expiryDate} 
                    productName={formData.productName} 
                    status={formData.isDutyPaid ? BatchStatus.DUTY_PAID : BatchStatus.CREATED}
                />
                <div className="mt-8 text-center px-4">
                    <p className="text-xs text-slate-400 leading-relaxed">
                        This DataMatrix enables real-time verification at pharmacies and hospitals, ensuring compliance with DSCSA and global track & trace mandates.
                    </p>
                </div>
            </div>
          </div>
        </div>
      )}

      {showTransferModal && selectedBatchIds.length > 0 && (
        <TransferModal 
          batches={getSelectedBatches()} 
          onClose={() => { setShowTransferModal(false); setSelectedBatchIds([]); }}
          onSubmit={handleTransferSubmit}
          currentUser={user}
        />
      )}

      {showReturnModal && selectedBatchForReturn && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
           <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                   <RotateCcw className="text-orange-500" />
                   <span>Initiate Return</span>
                </h3>
                <button onClick={() => setShowReturnModal(false)} className="text-slate-400 hover:text-slate-600">✕</button>
              </div>

              <div className="bg-orange-50 p-4 rounded-lg mb-6 border border-orange-100">
                 <p className="text-sm text-orange-900 font-medium">Returning: {selectedBatchForReturn.productName}</p>
                 <p className="text-xs text-orange-700 font-mono mt-1">{selectedBatchForReturn.batchID}</p>
                 <p className="text-xs text-orange-600 mt-1">Available to Return: {selectedBatchForReturn.quantity - (selectedBatchForReturn.totalReturnedQuantity || 0)} {selectedBatchForReturn.unit}</p>
              </div>

              <form onSubmit={handleReturnSubmit} className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Return To (GLN)</label>
                        <input 
                            required
                            className="w-full border border-slate-300 rounded-lg px-4 py-2 font-mono text-sm focus:ring-2 focus:ring-orange-500 outline-none"
                            value={returnData.toGLN}
                            onChange={e => setReturnData({...returnData, toGLN: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Quantity ({selectedBatchForReturn.unit})</label>
                        <input 
                            type="number"
                            required
                            min="1"
                            max={selectedBatchForReturn.quantity - (selectedBatchForReturn.totalReturnedQuantity || 0)}
                            className="w-full border border-slate-300 rounded-lg px-4 py-2 text-sm focus:ring-2 focus:ring-orange-500 outline-none"
                            value={returnData.quantityToReturn}
                            onChange={e => setReturnData({...returnData, quantityToReturn: parseInt(e.target.value)})}
                        />
                    </div>
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Reason</label>
                      <select 
                        className="w-full border border-slate-300 rounded-lg px-4 py-2 text-sm focus:ring-2 focus:ring-orange-500 outline-none bg-white"
                        value={returnData.reason}
                        onChange={e => setReturnData({...returnData, reason: e.target.value as ReturnReason})}
                      >
                         {Object.values(ReturnReason).map(r => (
                             <option key={r} value={r}>{r}</option>
                         ))}
                      </select>
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Refund Amount</label>
                      <input 
                        type="number"
                        className="w-full border border-slate-300 rounded-lg px-4 py-2 text-sm focus:ring-2 focus:ring-orange-500 outline-none"
                        value={returnData.refundAmount}
                        onChange={e => setReturnData({...returnData, refundAmount: parseFloat(e.target.value)})}
                      />
                  </div>

                  <div className="flex justify-end gap-2 pt-4 border-t border-slate-100 mt-6">
                      <button 
                        type="button"
                        onClick={() => setShowReturnModal(false)}
                        className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-medium"
                      >
                          Cancel
                      </button>
                      <button 
                        type="submit"
                        className="px-4 py-2 bg-orange-500 text-white rounded-lg font-bold hover:bg-orange-600 shadow-md"
                      >
                          Confirm Return
                      </button>
                  </div>
              </form>
           </div>
        </div>
      )}

      {showRecallModal && selectedBatchForRecall && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
           <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-6 border-t-4 border-red-600">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-red-700 flex items-center gap-2">
                   <AlertTriangle className="fill-red-100" />
                   <span>EMERGENCY RECALL</span>
                </h3>
                <button onClick={() => setShowRecallModal(false)} className="text-slate-400 hover:text-slate-600">✕</button>
              </div>

              <div className="bg-red-50 p-4 rounded-lg mb-6 border border-red-100">
                 <p className="text-sm font-bold text-red-900">Recalling: {selectedBatchForRecall.productName}</p>
                 <p className="text-xs text-red-700 font-mono mt-1">Batch ID: {selectedBatchForRecall.batchID}</p>
                 <p className="text-xs text-red-600 mt-2">
                    Warning: This action is irreversible. The batch status will be updated to RECALLED on the ledger immediately.
                 </p>
              </div>

              <form onSubmit={handleRecallSubmit} className="space-y-4">
                  <div>
                      <label className="block text-xs font-bold text-slate-600 uppercase mb-1">Reason for Recall</label>
                      <textarea 
                        required
                        className="w-full border border-slate-300 rounded-lg px-4 py-3 text-sm focus:ring-2 focus:ring-red-500 outline-none h-32"
                        placeholder="Describe the defect, contamination, or regulatory violation..."
                        value={recallReason}
                        onChange={e => setRecallReason(e.target.value)}
                      />
                  </div>

                  <div className="flex justify-end gap-2 pt-4 border-t border-slate-100 mt-2">
                      <button 
                        type="button"
                        onClick={() => setShowRecallModal(false)}
                        className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-medium"
                      >
                          Cancel
                      </button>
                      <button 
                        type="submit"
                        className="px-4 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 shadow-md flex items-center gap-2"
                      >
                          <AlertTriangle size={16} />
                          <span>CONFIRM RECALL</span>
                      </button>
                  </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default BatchManager;

export enum Sector {
  EXCISE = 'EXCISE',
  PHARMA = 'PHARMA',
  FMCG = 'FMCG',
  AGRICULTURE = 'AGRICULTURE',
  LOGISTICS = 'LOGISTICS'
}

export enum ERPType {
  SAP = 'SAP / ORACLE',
  TALLY = 'TALLY',
  ZOHO = 'ZOHO / ODOO',
  MARG = 'MARG ERP',
  MANUAL = 'NO ERP (MANUAL)'
}

export enum UserRole {
  MANUFACTURER = 'MANUFACTURER',
  DISTRIBUTOR = 'DISTRIBUTOR',
  RETAILER = 'RETAILER',
  REGULATOR = 'REGULATOR',
  AUDITOR = 'AUDITOR'
}

export enum BatchStatus {
  CREATED = 'CREATED',
  IN_TRANSIT = 'IN_TRANSIT',
  RECEIVED = 'RECEIVED',
  SOLD = 'SOLD',
  RECALLED = 'RECALLED',
  DESTROYED = 'DESTROYED',
  RETURNED = 'RETURNED',
  QUARANTINED = 'QUARANTINED',
  BONDED = 'BONDED',
  DUTY_PAID = 'DUTY_PAID',
  CONSUMED = 'CONSUMED'
}

export interface TraceEvent {
  eventID: string;
  type: string;
  timestamp: string;
  actorGLN: string;
  actorName: string;
  location: string;
  metadata?: Record<string, any>;
  txHash: string;
  previousHash: string;

  // Return specific fields
  returnReason?: ReturnReason;
  returnQuantity?: number;
  returnRecipientGLN?: string;
}

export interface Batch {
  batchID: string;
  gtin: string; 
  lotNumber: string;
  expiryDate: string; 
  quantity: number;
  unit: string;
  manufacturerGLN: string;
  currentOwnerGLN: string;
  intendedRecipientGLN?: string;
  status: BatchStatus;
  trace: TraceEvent[];
  productName: string;
  integrityHash?: string; 

  // Dynamic Context
  sector: Sector;
  country: string;

  // Industry Specific
  alcoholContent?: number; 
  category?: string;
  dutyPaid?: boolean;
  dosageForm?: string; // Pharma specific
  serialNumber?: string; // Pharma specific (SGTIN)

  // GST Compliance Fields
  hsnCode?: string;
  taxableValue?: number;
  taxRate?: number;
  taxAmount?: number;
  mrp?: number; // Maximum Retail Price (India Specific)

  // Return tracking
  totalReturnedQuantity?: number;

  blockchainId: string;
  genesisHash: string;
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  gln: string;
  orgName: string;
  country: string;
  sector: Sector;
  positionLabel: string;
  erpType: ERPType;
  erpStatus: 'CONNECTED' | 'DISCONNECTED' | 'PENDING';
  subCategories?: string[];
}

// Internal ERP Data Structures
export interface ProductionOrder {
  id: string;
  productName: string;
  plannedQty: number;
  actualQty: number;
  startDate: string;
