export enum ReturnReason {
  DAMAGED = 'DAMAGED',
  EXPIRED = 'EXPIRED',
  RECALLED = 'RECALLED',
  WRONG_ITEM = 'WRONG_ITEM',
  OTHER = 'OTHER'
}

export interface GSTDetails {
  hsnCode: string;
  taxableValue: number;
  taxRate: number;
  taxAmount: number;
  invoiceNo: string;
  invoiceDate: string;
}

export interface EWayBill {
  ewbNo: string;
  vehicleNo: string;
  fromPlace: string;
  toPlace: string;
  distanceKm: number;
  validUntil: string;
  generatedDate: string;
}

export enum PaymentStatus {
  PAID = 'PAID',
  UNPAID = 'UNPAID',
  PARTIAL = 'PARTIAL',
  WAIVED = 'WAIVED',
  CREDIT = 'CREDIT'
}

export interface PaymentDetails {
  totalAmount: number;
  amountPaid: number;
  amountRemaining: number;
  waivedAmount: number;
